ideas = []

def source(id, title, language, kind, url, verified, relevance, limitation, extra=None):
    sources.append(dict(id=id, title=title, language=language, kind=kind, url=url,
        verified=verified, relevance=relevance, limitation=limitation, extra=extra or []))

def idea(id, sid, title, basis, mechanic, difficulty, question, answer, media,
         adaptation, fit='Обычный вопрос', priority='Высокий', facts=None):
    ideas.append(dict(id=id, source_id=sid, title=title, basis=basis,
        mechanic=mechanic, difficulty=difficulty, question=question, answer=answer,
        media=media, adaptation=adaptation, dibs_fit=fit, priority=priority,
        example_origin='Авторский пример / адаптация; не вопрос из оригинальной игры',
        fact_sources=facts or []))

