TEMPLATE='''<!doctype html>
<html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Мемы и интернет — исследование игр для Dibs</title><style>__STYLE__</style></head><body>
<a class="back" href="svoyak-categories.html">← Каталог «Свояка»</a>
<h1>Мемы, приколы и интернет</h1>
<p class="meta">23 игры и формата · 50 карточек идей · 30 RU / 20 EN · проверено 03.11.2026</p>
<p class="intro">Русскоязычные мем-квизы, англоязычные шоу и игры для компании: что можно взять для своего поля Dibs. Поиск по категориям, примерам, ответам и источникам.</p>
<p class="notice"><strong>Для подготовки — со спойлерами.</strong> Это подборка открытых правил и описаний. Все примеры — наши адаптации; они не выдаются за вопросы из оригинальных игр. Готовые медиа и результаты опросов сюда не включены.</p>
<p><a href="internet-party-games.md">Markdown</a> · <a href="internet-party-games.json">JSON каталога</a> · <a href="#guide" id="to-guide">С чего начать</a></p>
<details class="intro"><summary>Методика, проверка источников и ограничения</summary><div id="method"></div></details>
<div class="tabs" role="tablist" aria-label="Раздел отчёта"><button role="tab" id="tab-ideas" aria-controls="ideas-panel" aria-selected="true">Категории и примеры — 50</button><button role="tab" id="tab-sources" aria-controls="sources-panel" aria-selected="false">Игры и источники — 23</button><button role="tab" id="tab-guide" aria-controls="guide" aria-selected="false">С чего начать</button></div>
<div class="tools" id="tools"><input id="search" type="search" placeholder="Окак, музыка, блеф, опрос…" aria-label="Поиск"><select id="lang" aria-label="Язык источника"><option value="">RU + EN</option><option value="RU">Русскоязычные</option><option value="EN">Англоязычные</option></select><select id="mechanic" aria-label="Механика"><option value="">Все механики</option></select><select id="fit" aria-label="Совместимость с Dibs"><option value="">Любая подготовка</option></select><button id="reset">Сбросить</button></div>
<div class="counts"><span class="muted" id="shown" aria-live="polite"></span><button id="answers">Открыть все ответы</button></div>
<section id="ideas-panel" role="tabpanel" aria-labelledby="tab-ideas"><div class="grid" id="idea-rows"></div></section>
<section id="sources-panel" role="tabpanel" aria-labelledby="tab-sources" hidden><div class="grid" id="source-rows"></div></section>
<section class="guide" id="guide" role="tabpanel" aria-labelledby="tab-guide" hidden><h2>Я бы начал с этого</h2><ul id="recommendations"></ul><h2>Черновой состав трёх раундов</h2><p>Это план подбора, не готовый пакет. У медийных вопросов нужно подготовить файлы, у опросных — собрать данные. Повторяющиеся разгадки замените.</p><div id="board"></div><p class="notice">Для правил со свободными ответами, голосованием и рисунками Dibs показывает инструкцию и позволяет ведущему выставить баллы. Специальных встроенных режимов для этих механик в приложении сейчас нет.</p></section>
<p id="empty" class="empty" hidden>Ничего не найдено. Попробуйте убрать фильтры.</p>
<footer>Локальный каталог в игнорируемой Git папке research. JSON имеет исследовательскую схему и не импортируется как игра Dibs. Вопросы существующих игр не изменялись.</footer>
<script id="catalog-data" type="application/json">__DATA__</script>
<script>
const d=JSON.parse(document.getElementById('catalog-data').textContent);
const $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=s=>String(s).toLocaleLowerCase('ru').replaceAll('ё','е');
const sourceById=Object.fromEntries(d.sources.map(s=>[s.id,s]));
let mode='ideas',allAnswers=false;
function link(url,title){return `<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(title)} ↗</a>`;}
$('method').innerHTML=d.methodology.map(m=>`<p>${esc(m)}</p>`).join('');
for(const key of ['mechanic','fit']){const field=key==='fit'?'dibs_fit':'mechanic';$(key).innerHTML+=[...new Set(d.ideas.map(i=>i[field]))].sort().map(x=>`<option>${esc(x)}</option>`).join('');}
$('recommendations').innerHTML=d.recommendations.map(r=>`<li><strong>${esc(r.title)}.</strong> ${esc(r.text)}</li>`).join('');
$('board').innerHTML=d.suggested_board.map(r=>`<h3>Раунд ${r.round}</h3><ul>${r.categories.map(c=>`<li>${esc(c.title)}: ${c.ideas.map(id=>`<a href="#idea-${id}" data-idea="${id}">${id}</a>`).join(', ')}</li>`).join('')}</ul>`).join('');
function matches(i){const s=sourceById[i.source_id],q=norm($('search').value.trim());return (!$('lang').value||s.language===$('lang').value)&&(!$('mechanic').value||i.mechanic===$('mechanic').value)&&(!$('fit').value||i.dibs_fit===$('fit').value)&&(!q||norm(JSON.stringify(i)+' '+JSON.stringify(s)).includes(q));}
function render(){
 const filtered=d.ideas.filter(matches),q=norm($('search').value.trim());
 const relevant=new Set(filtered.map(i=>i.source_id));
 const sf=d.sources.filter(s=>(!$('lang').value||s.language===$('lang').value)&&(!q||norm(JSON.stringify(s)).includes(q)||filtered.some(i=>i.source_id===s.id))&&(!($('mechanic').value||$('fit').value)||relevant.has(s.id)));
 $('idea-rows').innerHTML=filtered.map(i=>{const s=sourceById[i.source_id];return `<article class="card" id="idea-${i.id}"><div class="eyebrow">${i.id} · ${s.language} · ${esc(s.title)}</div><h3>${esc(i.title)}</h3><span class="pill">${esc(i.mechanic)}</span><span class="pill">${esc(i.difficulty)}</span><span class="pill">${esc(i.dibs_fit)}</span><p class="muted">${esc(i.basis)}</p><div class="sample"><div class="label">Пример · авторская адаптация</div><p>${esc(i.question)}</p><details class="answer" ${allAnswers?'open':''}><summary>Ответ / критерий</summary><p>${esc(i.answer)}</p></details></div><p><strong>Подготовка.</strong> ${esc(i.media)}</p><p><strong>В Dibs.</strong> ${esc(i.adaptation)}</p><div class="source-links">${link(s.url,'Источник механики')}${i.fact_sources.map(f=>link(f.url,'Проверка факта: '+f.title)).join(' ')}</div></article>`;}).join('');
 $('source-rows').innerHTML=sf.map(s=>`<article class="card" id="source-${s.id}"><div class="eyebrow">${s.id} · ${s.language} · ${esc(s.kind)}</div><h3>${esc(s.title)}</h3><p><strong>Проверено.</strong> ${esc(s.verified)}</p><p><strong>Зачем смотреть.</strong> ${esc(s.relevance)}</p><p><strong>Глубина обзора.</strong> ${esc(s.limitation)}</p><div class="source-links">${link(s.url,'Основной источник')}${s.extra.map(e=>link(e.url,e.title)).join(' ')}</div></article>`).join('');
 $('shown').textContent=mode==='ideas'?`Показано ${filtered.length} из 50 карточек`:mode==='sources'?`Показано ${sf.length} из 23 источников`:'Рекомендации по подготовке своей игры';
 $('empty').hidden=mode==='guide'||(mode==='ideas'?filtered.length:sf.length)>0;
 $('answers').hidden=mode!=='ideas';$('tools').hidden=mode==='guide';
}
function tab(next){mode=next;for(const m of ['ideas','sources','guide']){$('tab-'+m).setAttribute('aria-selected',String(m===next));$(m==='guide'?'guide':m+'-panel').hidden=m!==next;}render();}
for(const m of ['ideas','sources','guide'])$('tab-'+m).onclick=()=>tab(m);
for(const id of ['search','lang','mechanic','fit'])$(id).addEventListener(id==='search'?'input':'change',render);
$('reset').onclick=()=>{for(const id of ['search','lang','mechanic','fit'])$(id).value='';render();};
$('answers').onclick=()=>{allAnswers=!allAnswers;document.querySelectorAll('details.answer').forEach(x=>x.open=allAnswers);$('answers').textContent=allAnswers?'Скрыть все ответы':'Открыть все ответы';};
$('to-guide').onclick=()=>tab('guide');
document.addEventListener('click',e=>{const a=e.target.closest('a[data-idea]');if(!a)return;e.preventDefault();for(const id of ['search','lang','mechanic','fit'])$(id).value='';tab('ideas');$('idea-'+a.dataset.idea).scrollIntoView({behavior:'smooth'});history.replaceState(null,'','#idea-'+a.dataset.idea);});
render();
</script></body></html>'''
payload=json.dumps(data,ensure_ascii=False).replace('<','\\u003c').replace('&','\\u0026')
(ROOT/'internet-party-games.html').write_text(TEMPLATE.replace('__STYLE__',STYLE).replace('__DATA__',payload))
print(json.dumps(dict(sources=len(sources),ideas=len(ideas),ru=sum(i['language']=='RU' for i in ideas),en=sum(i['language']=='EN' for i in ideas)),ensure_ascii=False))
